{
  "_doc": "Channel identity. Every generated graphic, caption and template reads from here, so the look stays consistent across videos. Change the name/colours once and re-render.",
  "channel_name": "CRODIE",
  "tagline": "Minecraft, but it goes wrong",
  "colors": {
    "grass": "#92AE22",
    "gold": "#EF7718",
    "diamond": "#4FE0D6",
    "redstone": "#FF4B4B",
    "amethyst": "#B072FF",
    "ink": "#1B2112",
    "paper": "#FCF3E2",
    "leaf": "#437420",
    "olive": "#313B20",
    "cream": "#FCDFB5"
  },
  "fonts": {
    "display": {
      "family": "Minecraft Ten",
      "file": "Editing Pack/Fonts/Minecraft Ten.ttf"
    },
    "captions": {
      "family": "Luckiest Guy",
      "file": "Editing Pack/Fonts/Luckiest Guy.ttf"
    },
    "ui": {
      "family": "Minecraft",
      "file": "Editing Pack/Fonts/Minecraft Regular.otf"
    },
    "thumb": {
      "family": "LEMON MILK Bold",
      "file": "Editing Pack/Fonts/LEMON MILK Bold.otf"
    }
  },
  "avatar": {
    "dir": "brand/avatar",
    "skin": "brand/avatar/skin.png",
    "_note": "Crodie: one emote per mood (avatar.moods). Rebuild with: uv run mcs avatar build. A real 64x64 skin at avatar.skin + removing 'moods' switches back to pixel-skin mode.",
    "moods": {
      "neutral": "brand/crodie/emotes/thumbs_up.png",
      "happy": "brand/crodie/emotes/laughing_thumbs_up.png",
      "sad": "brand/crodie/emotes/teary_sad.png",
      "angry": "brand/crodie/emotes/angry_vein.png",
      "shocked": "brand/crodie/emotes/shocked_exclaim.png"
    }
  },
  "watermark": {
    "enabled": true,
    "image": "brand/crodie/logos/icon_c_grass_orange.png",
    "text": "@Crodie",
    "opacity": 0.85,
    "_note": "image = logo bug (top-right); remove 'image' to fall back to the text watermark"
  },
  "_colors_note": "Crodie palette (from the skin sheet): lime #92AE22, leaf #437420, orange #EF7718 (stored as 'gold' so every template accent follows), cream belly #FCDFB5, dark olive #313B20",
  "source_art": "../Crodie/ (banner, profile pic, skin sheet, asset sheet)",
  "logo": {
    "main": "brand/crodie/logos/logo_grass_main.png",
    "icon": "brand/crodie/logos/icon_c_grass_orange.png",
    "badge": "brand/crodie/logos/badge_wood_crown.png"
  }
}

