MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(1337);
  var title = String(v.title || "").toUpperCase();
  var sub = String(v.subtitle || "").trim();
  var palette = ["var(--grass)", "var(--gold)", "var(--diamond)", "var(--redstone)", "var(--amethyst)"];

  // --- title layout (pre-computed, font-load independent)
  var K = 0.53;
  var fit = MC.fit(title, d.vertical
    ? { maxWidth: W * 0.88, maxSize: 96, minSize: 30, k: K, maxLines: 3, maxHeight: H * 0.34 }
    : { maxWidth: W * 0.86, maxSize: 112, minSize: 30, k: K, maxLines: 2, maxHeight: H * 0.42 });
  var tEl = document.getElementById("tt-title");
  tEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(tEl, fit.lines);
  var titleH = fit.lines.length * fit.size;
  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var titleW = longest * fit.size * K;
  var Bpre = d.vertical ? 40 : 42;
  var groupH = titleH + fit.size * 0.22 + Bpre * 2 + (sub ? 14 + 40 : 0);
  var titleTop = H * (d.vertical ? 0.46 : 0.5) - groupH / 2;
  tEl.style.top = titleTop + "px";

  // --- block plinth under the title: two staggered rows
  var B = Bpre;
  var plinthW = Math.min(W * 0.92, Math.max(titleW + B * 2, B * 6));
  var cols = Math.max(4, Math.round(plinthW / B));
  var plinthTop = titleTop + titleH + fit.size * 0.22;
  var x0 = W / 2 - (cols * B) / 2;
  var bWrap = document.getElementById("tt-blocks");
  var blocks = [], targets = [];
  for (var r = 0; r < 2; r++) {
    var n = r === 0 ? cols : cols - 1;
    for (var c = 0; c < n; c++) {
      var b = document.createElement("div");
      b.className = "mc-block";
      b.style.width = B + "px"; b.style.height = B + "px";
      b.style.left = (x0 + c * B + (r === 1 ? B / 2 : 0)) + "px";
      b.style.top = (plinthTop + r * B) + "px";
      b.style.setProperty("--bc", r === 0 ? palette[(c * 2 + 1) % palette.length] : "var(--ink)");
      if (r === 1) b.style.borderColor = "#000";
      bWrap.appendChild(b);
      blocks.push(b);
      targets.push({ dx: (rnd() - 0.5) * W * 0.5, dy: -(H * 0.6 + rnd() * H * 0.4), rot: (rnd() - 0.5) * 200, delay: rnd() * 0.5 + r * 0.12 });
    }
  }

  // --- subtitle tag on the plinth
