  if (sub) {
    sEl.textContent = sub.toUpperCase();
    var sSize = d.vertical ? 30 : 30;
    sSize = Math.min(sSize, (W * 0.8) / (sub.length * 0.62));
    sEl.style.fontSize = Math.floor(sSize) + "px";
    sEl.style.top = (plinthTop + B * 2 + 14) + "px";
  } else {
    sEl.style.display = "none";
  }

  // --- dust particles for the slam
