def load_brand() -> dict:
    return json.loads(BRAND_JSON.read_text(encoding="utf-8"))


def _brand_lookup(brand: dict, dotted: str):
    cur = brand
    for part in dotted.split("."):
        cur = cur[part]
    return cur


def brand_css(brand: dict | None = None) -> str:
    brand = brand or load_brand()
    lines = ["/* GENERATED by mcstudio.motion from studio/brand/brand.json - do not edit. */"]
    for fam, fname in FONT_FACES:
        lines.append(f'@font-face {{ font-family: "{fam}"; src: url("fonts/{fname}"); font-display: block; }}')
    lines.append(":root {")
    for k, v in brand.get("colors", {}).items():
        lines.append(f"  --{k}: {v};")
    lines.append("}")
    return "\n".join(lines) + "\n"


# --------------------------------------------------------------------------- templates

