  function srcOf(x) { var s = String(x == null ? "" : x).trim(); return /^(data:|https?:|blob:)/i.test(s) ? s : ""; }
  function aspectOf(uri, dflt) {
    var m = /^data:[^;,]*;base64,(.*)$/i.exec(uri || ""); if (!m) return dflt;
    var h; try { h = atob(m[1].slice(0, 44)); } catch (e) { return dflt; }
    var u = function (i) { return h.charCodeAt(i) & 255; };
    if (h.slice(1, 4) === "PNG") {
      var w = (u(16) << 24 | u(17) << 16 | u(18) << 8 | u(19)) >>> 0, hh = (u(20) << 24 | u(21) << 16 | u(22) << 8 | u(23)) >>> 0;
      return w && hh ? w / hh : dflt;
    }
