    if (!s) return null;
    var i = document.createElement("img"); i.src = s; i.alt = "";
    i.setAttribute("data-layout-allow-overflow", ""); parent.appendChild(i); return i;
  }
  function box(el, x, y, w, h) {
    el.style.left = x.toFixed(1) + "px"; el.style.top = y.toFixed(1) + "px";
    el.style.width = w.toFixed(1) + "px"; el.style.height = h.toFixed(1) + "px";
  }

  var logoSrc = srcOf(v.logo), mascotSrc = srcOf(v.mascot);
  var tagline = String(v.tagline == null ? "" : v.tagline).trim().toUpperCase();
  var la = Math.max(0.4, Math.min(6, aspectOf(logoSrc, 2.3)));
  var ma = Math.max(0.3, Math.min(4, aspectOf(mascotSrc, 1.24)));

