  var safeTop = vert ? H * 0.105 : 0, safeBot = vert ? H * 0.735 : H;
  var logoW = vert ? Math.min(W * 0.86, 470) : Math.min(W * 0.56, 540);
  var logoH = logoW / la;
  if (logoH > H * (vert ? 0.24 : 0.46)) { logoH = H * (vert ? 0.24 : 0.46); logoW = logoH * la; }
  var logoCY = vert ? safeTop + logoH / 2 + 50 : H * 0.36;
