// ---- image helpers: motion.py inlines local paths as data: URIs; anything else draws nothing
function srcOf(x) { var s = String(x == null ? "" : x).trim(); return /^(data:|https?:|blob:)/i.test(s) ? s : ""; }
}

var logoSrc = srcOf(v.logo), mascotSrc = srcOf(v.mascot);

function box(el, x, y, w, h) {
  el.style.left = x.toFixed(1) + "px"; el.style.top = y.toFixed(1) + "px";
  el.style.width = w.toFixed(1) + "px"; el.style.height = h.toFixed(1) + "px";
}

