MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration, vert = d.vertical;

  //@@HELPERS

  var bannerSrc = srcOf(v.banner), emoteSrc = srcOf(v.emote);
  var doneText = String(v.done_text == null ? "" : v.done_text).trim().toUpperCase() || "SUBSCRIBED";
  var ba = Math.max(1, Math.min(6, aspectOf(bannerSrc, 620 / 251)));
  var ea = Math.max(0.4, Math.min(3, aspectOf(emoteSrc, 1)));

  // ---- layout (logical). Banner is 620px native: <= ~1.5x in full renders.
  var safeBot = vert ? H * 0.735 : H;
  var BW = vert ? Math.min(W * 0.87, 470) : 440, BH = BW / ba;
  var EH = vert ? 124 : 130, EW = EH * ea;
  var bx, by, ex, ey;
  if (vert) {
    bx = (W - BW) / 2; by = safeBot - BH - 8;
    ex = bx + BW * 0.53; ey = by - EH + BH * 0.16;
  } else {
    var gw = BW + 12 + EW;
    bx = (W - gw) / 2; by = H - BH - 34;
    ex = bx + BW + 12; ey = by + BH - EH - 8;
  }
  var banner = document.getElementById("cs-banner");
  box(banner, bx, by, BW, BH);
  addImg(document.getElementById("cs-art"), bannerSrc);
  addImg(document.getElementById("cs-grey"), bannerSrc);
  var emote = document.getElementById("cs-emote"), ebob = document.getElementById("cs-ebob");
  box(emote, ex, ey, EW, EH);
  addImg(ebob, emoteSrc);

  // plate over the sign text (fractions tuned for cta_subscribe.png)
  var plate = document.getElementById("cs-plate");
  var px0 = 0.395 * BW, py0 = 0.35 * BH, pw = 0.53 * BW, ph = 0.39 * BH;
  box(plate, px0, py0, pw, ph);
  var checkPx = Math.max(2, Math.round(ph * 0.055));
  var checkSvg = MC.pixelSVG([
    "......KKK",
    ".....KGGK",
    "KKK.KGGK.",
    "KGGKGGK..",
    ".KGGGK...",
    "..KGK....",
    "...K....."], { K: "#000000", G: "#92AE22" }, checkPx);
  var checkW = 9 * checkPx;
  var ck = document.getElementById("cs-check");
  ck.innerHTML = checkSvg;
  ck.style.marginLeft = Math.round(ph * 0.14) + "px";
  var done = document.getElementById("cs-done");
  var fs = Math.floor(Math.min(ph * 0.5, (pw - checkW - ph * 0.5) / (doneText.length * 0.6)));
  done.textContent = doneText; done.style.fontSize = Math.max(10, fs) + "px";

  // click point: the play button
  var cxp = 0.30 * BW, cyp = 0.64 * BH;
  var ripple = document.getElementById("cs-ripple");
  var rr = BH * 0.3;
  box(ripple, cxp - rr, cyp - rr, rr * 2, rr * 2);

  // pixel cursor (tip at the element's top-left)
  var cur = document.getElementById("cs-cursor");
  var cpx = vert ? 2.6 : 2.6;
  cur.innerHTML = MC.pixelSVG([
    "K..........",
    "KK.........",
    "KWK........",
    "KWWK.......",
    "KWWWK......",
    "KWWWWK.....",
    "KWWWWWK....",
    "KWWWWWWK...",
    "KWWWWWWWK..",
    "KWWWWWWWWK.",
    "KWWWWWKKKKK",
    "KWWKWWK....",
    "KWK.KWWK...",
    "KK..KWWK...",
    "K....KWWK..",
    ".....KWWK..",
    "......KK..."], { K: "#000000", W: "#ffffff" }, cpx);
  var cTipX = bx + cxp, cTipY = by + cyp;
  box(cur, cTipX - 1, cTipY - 1, 11 * cpx, 17 * cpx);

  // pixel bell at the banner's top-right
  var bell = document.getElementById("cs-bell"), swing = document.getElementById("cs-bswing");
  var bpx = vert ? 3.6 : 3.6, bellW = 13 * bpx, bellH = 14 * bpx;
  swing.innerHTML = MC.pixelSVG([
    "......K......",
    ".....KYK.....",
    "....KYYYK....",
    "...KYYWYYK...",
    "..KYYWYYYYK..",
    "..KYWYYYYYK..",
    "..KYWYYYYOK..",
    "..KYYYYYYOK..",
    ".KYYYYYYYOOK.",
    "KYYYYYYYYYOOK",
    "KOOOOOOOOOOOK",
    ".KKKKKKKKKKK.",
    ".....KOK.....",
    "......K......"], { K: "#000000", Y: "#FFC93C", O: "#EF7718", W: "#FFF6C8" }, bpx);
  var bellX = bx + BW * 0.9 - bellW / 2, bellY = by - bellH * 0.35;
  box(bell, bellX, bellY, bellW, bellH);
  var waves = document.getElementById("cs-bwaves"), waveEls = [];
  [[-1, -0.25, -30], [-1, 0.12, 0], [1, -0.25, 30], [1, 0.12, 0]].forEach(function (wv) {
    var e = document.createElement("div");
    e.className = "cs-wave";
    e.setAttribute("data-layout-allow-overlap", ""); e.setAttribute("data-layout-allow-overflow", "");
    var lw = bellW * 0.32, lh = Math.max(4, bpx * 1.2);
    box(e, bellW / 2 + wv[0] * bellW * 0.72 - lw / 2, bellH * (0.45 + wv[1]) - lh / 2, lw, lh);
    e.style.transform = "rotate(" + (wv[0] * wv[2]) + "deg)";
    waves.appendChild(e); waveEls.push(e);
  });

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var wrap = document.getElementById("cs-wrap"), press = document.getElementById("cs-press");
  var grey = document.getElementById("cs-grey");
  var OUT = D - 0.42, END = D - 0.04;
  var CLICK = 1.0;
  gsap.set(press, { transformOrigin: (cxp / BW * 100).toFixed(1) + "% " + (cyp / BH * 100).toFixed(1) + "%" });
  gsap.set(plate, { transformOrigin: "50% 50%" });
  gsap.set(swing, { transformOrigin: "50% 8%" });
  gsap.set(ebob, { transformOrigin: "50% 70%" });

  // 1) banner slides in from the left
  var off = -(bx + BW + 40);
  tl.fromTo(banner, { x: off }, { x: 0, duration: 0.42, ease: "back.out(1.4)" }, 0);
  tl.fromTo(press, { skewX: 10, rotation: -3 }, { skewX: 0, rotation: 0, duration: 0.5, ease: "back.out(2.4)" }, 0.04);

  // 2) cursor glides to the button and clicks
  var cdx = vert ? W * 0.45 : W * 0.32, cdy = vert ? H * 0.12 : H * 0.3;
  tl.fromTo(cur, { x: cdx, y: cdy, opacity: 0 }, { keyframes: [
    { opacity: 1, x: cdx * 0.55, y: cdy * 0.25, duration: 0.3, ease: "power1.out" },
    { x: 0, y: 0, duration: 0.3, ease: "power2.inOut" }] }, 0.36);
  tl.to(cur, { keyframes: [{ scale: 0.8, duration: 0.06, ease: "power2.out" }, { scale: 1, duration: 0.12, ease: "back.out(3)" }], transformOrigin: "0% 0%" }, CLICK);
  tl.to(press, { keyframes: [
    { scaleX: 1.03, scaleY: 0.9, duration: 0.06, ease: "power2.out" },
    { scaleX: 1, scaleY: 1, duration: 0.3, ease: "back.out(3)" }] }, CLICK);
  tl.fromTo(ripple, { scale: 0.3, opacity: 0 }, { keyframes: [
    { scale: 0.45, opacity: 1, duration: 0.03, ease: "none" },
    { scale: 1.5, opacity: 0, duration: 0.36, ease: "power2.out" }] }, CLICK + 0.02);
  tl.fromTo(grey, { opacity: 0 }, { opacity: 1, duration: 0.08, ease: "none", immediateRender: true }, CLICK + 0.04);
  tl.fromTo(plate, { scaleY: 0, scaleX: 0.9, opacity: 0 }, { scaleY: 1, scaleX: 1, opacity: 1, duration: 0.24, ease: "back.out(2.2)" }, CLICK + 0.06);
  tl.fromTo(ck, { scale: 0, rotation: -40 }, { scale: 1, rotation: 0, duration: 0.26, ease: "back.out(3)" }, CLICK + 0.22);
  // cursor wanders off
  tl.to(cur, { x: cdx * 0.5, y: cdy * 0.7, opacity: 0, duration: 0.34, ease: "power2.in" }, CLICK + 0.36);

  // 3) bell pops and rings
  var BELL = CLICK + 0.34;
  tl.fromTo(bell, { scale: 0, rotation: -30 }, { scale: 1, rotation: 0, duration: 0.28, ease: "back.out(2.6)" }, BELL);
  var ring = [-24, 20, -16, 12, -8, 5, 0], kf = ring.map(function (r) { return { rotation: r, duration: 0.09, ease: "sine.inOut" }; });
  tl.fromTo(swing, { rotation: 0 }, { keyframes: kf, immediateRender: false }, BELL + 0.2);
  waveEls.forEach(function (e, i) {
    tl.fromTo(e, { opacity: 0, scale: 0.4 }, { keyframes: [
      { opacity: 1, scale: 1, duration: 0.08, ease: "power2.out" },
      { opacity: 1, duration: 0.18 },
      { opacity: 0, scale: 0.6, duration: 0.14, ease: "power1.in" }] }, BELL + 0.22 + (i % 2) * 0.06);
    tl.fromTo(e, { opacity: 0 }, { keyframes: [
      { opacity: 1, duration: 0.06 }, { opacity: 0, duration: 0.14, delay: 0.1 }], immediateRender: false }, BELL + 0.62 + (i % 2) * 0.05);
  });

  // 4) emote pops beside
  var EMO = CLICK + 0.55;
  if (emoteSrc) {
    tl.fromTo(emote, { scale: 0, rotation: -25 }, { scale: 1, rotation: vert ? 6 : 5, duration: 0.42, ease: "elastic.out(1, 0.55)" }, EMO);
    var hold = OUT - (EMO + 0.45);
    if (hold > 0.3) {
      var n = Math.max(1, Math.round(hold / 0.38));
      tl.fromTo(ebob, { y: 0 }, { y: -6, duration: hold / n, ease: "sine.inOut", repeat: n - 1, yoyo: true, immediateRender: false }, EMO + 0.45);
    }
  } else {
    tl.set(emote, { opacity: 0 }, 0);
  }

  // 5) exit
  if (emoteSrc) tl.to(emote, { scale: 0, rotation: 40, duration: 0.2, ease: "back.in(2)" }, OUT);
  tl.to(bell, { scale: 0, rotation: 30, duration: 0.18, ease: "back.in(2)" }, OUT + 0.04);
  tl.to(press, { skewX: -8, duration: 0.3, ease: "power2.in" }, OUT + 0.08);
  tl.to(banner, { x: off, duration: 0.3, ease: "back.in(1.3)" }, OUT + 0.08);

  tl.fromTo(wrap, { opacity: 0 }, { opacity: 1, duration: 0.001, immediateRender: true }, 0.004);
  tl.set(wrap, { opacity: 0 }, END);
  return tl;
});

