input.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration, vert = d.vertical;

  //@@HELPERS

  var src = srcOf(v.image);
  var side = String(v.side || "right").trim().toLowerCase();
  if (["left", "right", "bottom"].indexOf(side) < 0) side = "right";
  var text = String(v.text == null ? "" : v.text).trim();
  var ia = Math.max(0.25, Math.min(4, aspectOf(src, 155 / 317)));

  // ---- layout (logical). Default art is 317px tall: <= ~1.65x in full renders.
  var safeTop = vert ? H * 0.105 : 0, safeBot = vert ? H * 0.735 : H;
  var ih = vert ? 262 : 250, iw = ih * ia;
  var maxW = side === "bottom" ? W * 0.5 : W * 0.42;
  if (iw > maxW) { iw = maxW; ih = iw / ia; }
  var clip = document.getElementById("cp-clip"), slide = document.getElementById("cp-slide");
  var wig = document.getElementById("cp-wig"), imgBox = document.getElementById("cp-img");
  addImg(imgBox, src);
  var x, y, clipH, fromX = 0, fromY = 0, pivot;
  var faceFx = 0.36, faceFy = 0.26;                     // face position as a fraction of the (unmirrored) art
  if (side === "bottom") {
    clipH = safeBot;
    x = W * (vert ? 0.56 : 0.64) - iw / 2;
    y = clipH - ih * 0.74;                               // top ~74% visible
    fromY = ih * 0.8 + 20; pivot = "50% 100%";
  } else {
    clipH = H;
    y = vert ? safeTop + (safeBot - safeTop - ih) / 2 : H * 0.9 - ih;
    x = side === "right" ? W - iw : 0;
    fromX = side === "right" ? iw + 20 : -(iw + 20);
    pivot = side === "right" ? "100% 100%" : "0% 100%";
  }
  box(clip, 0, 0, W, clipH);
  box(slide, x, y, iw, ih);
  if (side === "left") gsap.set(imgBox, { scaleX: -1 });
  var faceX = x + iw * (side === "left" ? 1 - faceFx : faceFx), faceY = y + ih * faceFy;

  // ---- speech bubble on the inner side of the face
  var bub = document.getElementById("cp-bubble"), tEl = document.getElementById("cp-text"), tail = document.getElementById("cp-tail");
  var bw = 0, bh = 0, bx = 0, by = 0, tailSide = 1;
  if (text) {
    var fs = Math.floor(Math.min(22, (W * (vert ? 0.5 : 0.3)) / (text.length * 0.62)));
    fs = Math.max(11, fs);
    tEl.textContent = text; tEl.style.fontSize = fs + "px";
    bw = text.length * fs * 0.62 + fs * 1.4; bh = fs * 2.0;
    if (side === "right") { bx = faceX - bw - 18; by = faceY - bh - 18; tailSide = 1; }
    else if (side === "left") { bx = faceX + 18; by = faceY - bh - 18; tailSide = -1; }
    else { bx = x + iw * 0.18 - bw; by = y + ih * 0.12 - bh; tailSide = 1; }
    bx = Math.max(10, Math.min(W - bw - 10, bx));
    by = Math.max(safeTop + 8, by);
    box(bub, bx, by, bw, bh);
    // tail: a rotated square peeking out of the bottom edge, toward the face
    tail.style.left = (tailSide > 0 ? bw - 34 : 16).toFixed(1) + "px";
    tail.style.top = (bh - 10).toFixed(1) + "px";
  } else {
    bub.style.display = "none";
  }

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var wrap = document.getElementById("cp-wrap");
  var IN = 0.36, OUT = D - 0.34, END = D - 0.04;
  gsap.set(wig, { transformOrigin: pivot });
  gsap.set(bub, { transformOrigin: (tailSide > 0 ? "85%" : "15%") + " 100%" });

  if (!src) { tl.set(wrap, { opacity: 0 }, 0); tl.set(wrap, { opacity: 0 }, D); return tl; }

  // 1) peek in
  tl.fromTo(slide, { x: fromX, y: fromY }, { x: 0, y: 0, duration: IN, ease: "back.out(1.5)" }, 0);
