    else { bx = x + iw * 0.18 - bw; by = y + ih * 0.12 - bh; tailSide = 1; }
    bx = Math.max(10, Math.min(W - bw - 10, bx));
    by = Math.max(safeTop + 8, by);
    box(bub, bx, by, bw, bh);
    // tail: a rotated square peeking out of the bottom edge, toward the face
    tail.style.left = (tailSide > 0 ? bw - 34 : 16).toFixed(1) + "px";
    tail.style.top = (bh - 10).toFixed(1) + "px";
  } else {
    bub.style.display = "none";
  }

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var wrap = document.getElementById("cp-wrap");
  var IN = 0.36, OUT = D - 0.34, END = D - 0.04;
  gsap.set(wig, { transformOrigin: pivot });
  gsap.set(bub, { transformOrigin: (tailSide > 0 ? "85%" : "15%") + " 100%" });

  if (!src) { tl.set(wrap, { opacity: 0 }, 0); tl.set(wrap, { opacity: 0 }, D); return tl; }

  // 1) peek in
  tl.fromTo(slide, { x: fromX, y: fromY }, { x: 0, y: 0, duration: IN, ease: "back.out(1.5)" }, 0);
  var lean = side === "right" ? -1 : 1;                 // lean toward the screen centre
  if (side === "bottom") lean = -1;
  tl.fromTo(wig, { rotation: lean * 6 }, { rotation: 0, duration: 0.42, ease: "back.out(2.5)" }, 0.08);

  // 2) wiggle through the hold (finite)
  var w0 = IN + 0.16, hold = OUT - 0.08 - w0;
  if (hold > 0.2) {
    var n = Math.max(2, Math.round(hold / 0.26)), ks = [];
    for (var i = 0; i < n; i++) ks.push({ rotation: (i % 2 ? -1 : 1) * (i === n - 1 ? 0 : 3.2), y: (i % 2 ? 0 : -3), duration: hold / n, ease: "sine.inOut" });
    ks[n - 1].rotation = 0; ks[n - 1].y = 0;
    tl.to(wig, { keyframes: ks }, w0);
  }

  // 3) bubble
  if (text) {
    var b0 = IN + 0.1, b1 = Math.max(b0 + 0.4, OUT - 0.14);
    tl.fromTo(bub, { scale: 0, rotation: -tailSide * 10 }, { scale: 1, rotation: -tailSide * 2, duration: 0.28, ease: "back.out(2.6)" }, b0);
    tl.to(bub, { scale: 0, duration: 0.12, ease: "back.in(2)" }, b1);
  }

  // 4) duck back: tiny anticipation, then out fast
  if (side === "bottom") {
    tl.to(slide, { keyframes: [{ y: -8, duration: 0.07, ease: "power1.out" }, { y: ih * 0.8 + 20, duration: 0.22, ease: "power3.in" }] }, OUT);
  } else {
    tl.to(slide, { keyframes: [{ x: -fromX * 0.04, duration: 0.07, ease: "power1.out" }, { x: fromX, duration: 0.22, ease: "power3.in" }] }, OUT);
  }

  tl.fromTo(wrap, { opacity: 0 }, { opacity: 1, duration: 0.001, immediateRender: true }, 0.004);
  tl.set(wrap, { opacity: 0 }, END);
  return tl;
});

