MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration, vert = d.vertical;
  var rnd = MC.rng(5150);

  //@@HELPERS

  var headSrc = srcOf(v.head);
  var title = String(v.title == null ? "" : v.title).trim().toUpperCase() || " ";
  var sub = String(v.subtitle == null ? "" : v.subtitle).trim().toUpperCase();
  var ha = Math.max(0.4, Math.min(2.5, aspectOf(headSrc, 165 / 208)));

  // ---- layout (logical). Head art is 208px tall: 120 logical = 240px in full renders.
  var safeBot = vert ? H * 0.735 : H;
  var HH = vert ? 124 : 120, HW = HH * ha;
  if (!headSrc) { HW = 0; }
  var SH = vert ? 62 : 60;
  var tSize = Math.floor(Math.min(vert ? 36 : 38, (W * (vert ? 0.56 : 0.44)) / (Math.max(title.length, 3) * 0.56)));
  var subSize = Math.floor(Math.min(vert ? 17 : 17, (W * (vert ? 0.66 : 0.46)) / (Math.max(sub.length, 1) * 0.62)));
  var signX = HW * 0.58, signY = headSrc ? HH * 0.36 : 0;
  var padL = Math.round(HW * 0.42 + 16), padR = Math.round(tSize * 0.7 + 8);

  var sign = document.getElementById("cl-sign");
  sign.style.left = signX.toFixed(1) + "px"; sign.style.top = signY.toFixed(1) + "px";
  sign.style.height = SH + "px";
  sign.style.padding = "0 " + padR + "px 0 " + padL + "px";
  sign.style.display = "flex"; sign.style.alignItems = "center";
  var tclip = document.getElementById("cl-tclip"), tEl = document.getElementById("cl-title");
  tEl.textContent = title; tEl.style.fontSize = tSize + "px";
  tclip.style.padding = "4px 4px " + Math.round(tSize * 0.18) + "px 2px";

  var subwrap = document.getElementById("cl-subwrap"), sEl = document.getElementById("cl-sub");
  var subH = 0;
  if (sub) {
    sEl.textContent = sub; sEl.style.fontSize = subSize + "px";
    sEl.style.padding = Math.round(subSize * 0.45) + "px " + Math.round(subSize * 0.7) + "px " + Math.round(subSize * 0.3) + "px";
    subwrap.style.left = (signX + padL - 6).toFixed(1) + "px";
    subwrap.style.top = (signY + SH - 3).toFixed(1) + "px";
    subH = subSize * 1.75 + 12;
  } else {
    subwrap.style.display = "none";
  }

  var head = document.getElementById("cl-head");
  box(head, 0, 0, HW, HH);
  addImg(head, headSrc);

  var groupH = Math.max(HH + 4, signY + SH + subH);
  var g = document.getElementById("cl-group");
  g.style.left = (vert ? 22 : 34) + "px";
  g.style.top = ((vert ? safeBot - 10 : H - 38) - groupH).toFixed(1) + "px";

  // vine leaves on the sign corners (percent positions: the sign width follows the text)
  var leafSvg = MC.pixelSVG([
    "...KK...",
    "..KLLK..",
    ".KLLlLK.",
    "KLLlLLLK",
    "KLlLLLK.",
    ".KLLLK..",
    "..KDK...",
    "...K...."], { K: "#1e3510", L: "#5f9a2a", l: "#92AE22", D: "#2f5418" }, 1);
  var leafWrap = document.getElementById("cl-leaves"), leaves = [];
  var LS = vert ? 22 : 21;
  [[100, -38, 20], [100, -8, 70], [92, -55, -15], [100, 30, 120], [62, -60, 10], [38, -58, -30]].forEach(function (L, i) {
    var e = document.createElement("div");
    e.className = "cl-leaf";
    e.setAttribute("data-layout-allow-overlap", ""); e.setAttribute("data-layout-allow-overflow", "");
    var s = Math.round(LS * (0.8 + rnd() * 0.4));
    e.style.width = e.style.height = s + "px";
    e.style.left = "calc(" + L[0] + "% - " + Math.round(s * 0.5) + "px)";
    e.style.top = Math.round(SH * (L[1] / 100) + (L[1] > 0 ? 0 : SH * 0.08)) + "px";
    e.innerHTML = leafSvg.replace('width="8" height="8"', 'width="100%" height="100%"');
    leafWrap.appendChild(e);
    leaves.push({ el: e, rot: L[2] });
  });

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var wrap = document.getElementById("cl-wrap");
  var OUT = D - 0.46, END = D - 0.04;
  gsap.set(head, { transformOrigin: "50% 85%" });
  gsap.set(sign, { transformOrigin: "0% 50%" });
  leaves.forEach(function (L) { gsap.set(L.el, { transformOrigin: "50% 90%", rotation: L.rot }); });

  if (headSrc) tl.fromTo(head, { scale: 0.2, y: 40, rotation: -25 }, { scale: 1, y: 0, rotation: 0, duration: 0.36, ease: "back.out(2.2)" }, 0);
  tl.fromTo(sign, { scaleX: 0 }, { scaleX: 1, duration: 0.32, ease: "back.out(1.3)" }, 0.14);
  tl.fromTo(tEl, { y: SH }, { y: 0, duration: 0.26, ease: "back.out(2)" }, 0.3);
  if (sub) tl.fromTo(sEl, { yPercent: -130 }, { yPercent: 0, duration: 0.26, ease: "back.out(2)" }, 0.44);
  leaves.forEach(function (L, i) {
    tl.fromTo(L.el, { scale: 0 }, { scale: 1, duration: 0.24, ease: "back.out(3)" }, 0.36 + i * 0.04);
  });
  // hold: leaves sway, head hops once (finite)
  var h0 = 0.8, hold = OUT - h0;
  if (hold > 0.3) {
    leaves.forEach(function (L, i) {
      var n = Math.max(1, Math.round(hold / 0.5));
      tl.fromTo(L.el, { rotation: L.rot }, { rotation: L.rot + (i % 2 ? -10 : 10), duration: hold / n, ease: "sine.inOut", repeat: n - 1, yoyo: true, immediateRender: false }, h0);
    });
  }
  if (headSrc && hold > 0.5) {
    tl.to(head, { keyframes: [
      { y: -12, rotation: -8, duration: 0.13, ease: "power2.out" },
      { y: 0, rotation: 0, duration: 0.22, ease: "bounce.out" }] }, h0 + 0.1);
    if (hold > 1.4) tl.to(head, { keyframes: [{ rotation: 7, duration: 0.14, ease: "sine.inOut" }, { rotation: -4, duration: 0.14 }, { rotation: 0, duration: 0.14 }] }, h0 + Math.min(1.1, hold - 0.5));
  }
  // exit
  if (sub) tl.to(sEl, { yPercent: -130, duration: 0.16, ease: "power2.in" }, OUT);
  tl.to(tEl, { y: -SH, duration: 0.16, ease: "power2.in" }, OUT + 0.04);
  leaves.forEach(function (L) { tl.to(L.el, { scale: 0, duration: 0.14, ease: "power2.in" }, OUT + 0.02); });
  tl.to(sign, { scaleX: 0, duration: 0.22, ease: "power3.in" }, OUT + 0.12);
  if (headSrc) tl.to(head, { scale: 0, rotation: 25, y: 20, duration: 0.2, ease: "back.in(2)" }, OUT + 0.2);

  tl.fromTo(wrap, { opacity: 0 }, { opacity: 1, duration: 0.001, immediateRender: true }, 0.004);
  tl.set(wrap, { opacity: 0 }, END);
  return tl;
});

