input.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration, vert = d.vertical;

  //@@HELPERS

  var frameSrc = srcOf(v.frame), e1Src = srcOf(v.emote), e2Src = srcOf(v.emote2);
  var label = String(v.label == null ? "" : v.label).trim().toUpperCase();
  var pos = String(v.position || "bottom-right").trim().toLowerCase().replace(/[\s_]+/g, "-");
  if (["bottom-right", "bottom-left", "top-right", "top-left"].indexOf(pos) < 0) pos = "bottom-right";
  var right = /right/.test(pos), bottom = /bottom/.test(pos);
  var fa = Math.max(0.6, Math.min(2.5, aspectOf(frameSrc, 564 / 428)));

  // ---- layout (logical). Frame art is 564px wide: 300 logical = 600px in full renders.
  var safeTop = vert ? H * 0.105 : 0, safeBot = vert ? H * 0.735 : H;
  var FW = vert ? 300 : 300, FH = FW / fa;
  var inset = vert ? 14 : 20;
  var labelRoom = label ? 22 : 0;
  var cx = right ? W - inset - FW : inset;
  var cy = bottom ? safeBot - (vert ? 8 : inset) - FH : safeTop + (vert ? 8 : inset) + labelRoom;
  var cam = document.getElementById("cr-cam");
  box(cam, cx, cy, FW, FH);
  addImg(document.getElementById("cr-frame"), frameSrc);

  // window (transparent hole of frame_facecam_wave): x 0.14-0.865, y 0.34-0.73. Backdrop slightly bigger, hidden under the frame.
  var wx0 = 0.13, wx1 = 0.875, wy0 = 0.32, wy1 = 0.76;
  box(document.getElementById("cr-back"), FW * wx0, FH * wy0, FW * (wx1 - wx0), FH * (wy1 - wy0));
  var win = document.getElementById("cr-win");
  var winW = FW * (wx1 - wx0), winH = FH * (wy1 - wy0);
  box(win, FW * wx0, FH * wy0, winW, winH);

  var EH = winH * 0.98;
  var emotes = [];
  [["cr-e1", e1Src], ["cr-e2", e2Src]].forEach(function (p) {
    var el = document.getElementById(p[0]);
    var a = Math.max(0.4, Math.min(3, aspectOf(p[1], 1.15)));
    var ew = Math.min(EH * a, winW * 0.9), eh = ew / a;
    box(el, (winW - ew) / 2, winH - eh + 4, ew, eh);
    addImg(el.querySelector(".cr-bob"), p[1]);
    emotes.push({ el: el, bob: el.querySelector(".cr-bob"), h: eh, ok: !!p[1] });
  });

  // label tag on the frame's top-left corner
  var lab = document.getElementById("cr-label");
  if (label) {
    var ls = Math.floor(Math.min(19, (FW * 0.62) / (label.length * 0.6)));
    lab.textContent = label; lab.style.fontSize = ls + "px";
    lab.style.padding = Math.round(ls * 0.42) + "px " + Math.round(ls * 0.55) + "px " + Math.round(ls * 0.22) + "px";
    lab.style.left = (FW * 0.02).toFixed(1) + "px";
    lab.style.top = (-ls * 0.55).toFixed(1) + "px";
  } else {
    lab.style.display = "none";
  }

  // ---- timeline
  var tl = gsap.timeline({ paused: true });
  var wrap = document.getElementById("cr-wrap");
  var OUT = D - 0.3, END = D - 0.04;
  var origin = (right ? "100%" : "0%") + " " + (bottom ? "100%" : "0%");
  gsap.set(cam, { transformOrigin: origin });
  gsap.set(lab, { transformOrigin: "20% 80%" });
  emotes.forEach(function (e) { gsap.set(e.bob, { transformOrigin: "50% 100%" }); });

  if (!frameSrc && !e1Src) { tl.set(wrap, { opacity: 0 }, 0); tl.set(wrap, { opacity: 0 }, D); return tl; }

  // 1) cam pops out of the corner
  tl.fromTo(cam, { scale: 0, rotation: right ? 10 : -10 }, { scale: 1, rotation: right ? -1.5 : 1.5, duration: 0.36, ease: "back.out(1.8)" }, 0);
  if (label) tl.fromTo(lab, { scale: 0, rotation: -25 }, { scale: 1, rotation: -6, duration: 0.3, ease: "back.out(2.6)" }, 0.3);

  // 2) emote springs up, bounces; optional swap to the second emote halfway
  var E1 = emotes[0], E2 = emotes[1];
  var swap = E2.ok && (OUT - 0.5) > 0.9;
  tl.set(E2.el, { opacity: 0 }, 0);
