MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration, vert = d.vertical;

  //@@HELPERS

  var frameSrc = srcOf(v.frame), e1Src = srcOf(v.emote), e2Src = srcOf(v.emote2);
  var label = String(v.label == null ? "" : v.label).trim().toUpperCase();
  var pos = String(v.position || "bottom-right").trim().toLowerCase().replace(/[\s_]+/g, "-");
  if (["bottom-right", "bottom-left", "top-right", "top-left"].indexOf(pos) < 0) pos = "bottom-right";
  var right = /right/.test(pos), bottom = /bottom/.test(pos);
  var fa = Math.max(0.6, Math.min(2.5, aspectOf(frameSrc, 564 / 428)));

  // ---- layout (logical). Frame art is 564px wide: 300 logical = 600px in full renders.
  var safeTop = vert ? H * 0.105 : 0, safeBot = vert ? H * 0.735 : H;
  var FW = vert ? 300 : 300, FH = FW / fa;
  var inset = vert ? 14 : 20;
  var labelRoom = label ? 22 : 0;
  var cx = right ? W - inset - FW : inset;
  var cy = bottom ? safeBot - (vert ? 8 : inset) - FH : safeTop + (vert ? 8 : inset) + labelRoom;
  var cam = document.getElementById("cr-cam");
  box(cam, cx, cy, FW, FH);
  addImg(document.getElementById("cr-frame"), frameSrc);

  // window (transparent hole of frame_facecam_wave): x 0.14-0.865, y 0.34-0.73. Backdrop slightly bigger, hidden under the frame.
  var wx0 = 0.13, wx1 = 0.875, wy0 = 0.32, wy1 = 0.76;
  box(document.getElementById("cr-back"), FW * wx0, FH * wy0, FW * (wx1 - wx0), FH * (wy1 - wy0));
  var win = document.getElementById("cr-win");
  var winW = FW * (wx1 - wx0), winH = FH * (wy1 - wy0);
  box(win, FW * wx0, FH * wy0, winW, winH);

  var EH = winH * 0.98;
